/* Platform MIT wrapper. Derived from the RSA Data Security, Inc. MD5 Message-Digest Algorithm. */
importScripts('/vendor/blueimp-md5/md5-binary.js');
self.onmessage=({data})=>{try{const f=data.file;if(!(f instanceof Blob)||f.size>8*1024*1024)throw Error('文件超过8MiB或无法读取');const read=new FileReaderSync(),parts=[];for(let pos=0;pos<f.size;pos+=1048576){const bytes=new Uint8Array(read.readAsArrayBuffer(f.slice(pos,pos+1048576)));let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode.apply(null,bytes.subarray(i,i+32768));parts.push(s);self.postMessage({progress:Math.min(pos+1048576,f.size)});}const hash=self.fileMD5Binary(parts.join(''));if(!/^[0-9a-f]{32}$/.test(hash))throw Error('指纹结果无效');self.postMessage({ok:true,hash});}catch(e){self.postMessage({ok:false,error:e instanceof Error?e.message:'文件读取失败'});}};
